'use strict';
const $=s=>document.querySelector(s), A=AudioBook;
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+'-'+Math.random().toString(36).slice(2);
const clip=(label,script='')=>({id:uid(),label,script,blob:null,duration:0,trimStart:0,trimEnd:null,version:0});
const question=(n,count=0)=>({id:uid(),stem:clip('第 '+n+' 題 · 題幹',''),arrangement:{mode:'single',recordOptions:count>0,optionCount:count||3},options:Array.from({length:count},(_,i)=>clip('選項 '+String.fromCharCode(65+i),''))});
const section=(n,count=0)=>({id:uid(),title:'第'+['一','二','三','四','五','六','七','八','九','十'][n-1]+'大題',prompt:clip('大題引導語',n===1?'Listen and choose. 聽一聽，選出正確的答案。':''),questions:[question(1,count),question(2,count)]});
const fresh=()=>({format:'listenbook',version:1,title:'我的第一份聽力測驗',intro:[{...clip('英文開場','Hello, everyone. This is the English listening test.'),lang:'en'},{...clip('中文開場','各位同學好，接下來是英語聽力測驗。'),lang:'zh'},{...clip('英文作答說明','Please listen carefully and choose the correct answer.'),lang:'en'},{...clip('中文作答說明','請仔細聆聽，並依照題目選出正確的答案。'),lang:'zh'}],roles:{A:{name:'說話者 1',tone:'natural'},B:{name:'說話者 2',tone:'warm'}},start:clip('測驗開始提醒','The listening test begins now. 聽力測驗現在開始。'),sections:[section(1),section(2,0)],replay:{...clip('重播提醒','現在將重播一遍。You will now hear the listening part again.'),omitFromPlayback:true},end:clip('測驗結束提醒','聽力測驗結束，請繼續完成書寫測驗。This is the end of the listening test. Please continue with the written test.'),settings:{introGap:1,dialogueGap:.6,sectionGap:5,questionGap:3,optionGap:3,roundGap:5,repeats:1,rounds:2,noiseCapture:true,cleanup:true,normalize:true,autoNext:true,silenceThreshold:2,sampleRate:44100}});
let lastAudioUndo=null;
let previewEpoch=0;
let state=fresh(),active='intro',page='record',db,saveTimer,saveChain=Promise.resolve(),rec=null,building=false,previewAudio=null,previewClipId=null,previewURL=null,fullURL=null,compiledBlob=null,importTarget=null,editClip=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>'<svg aria-hidden="true"><use href="#i-'+n+'"/></svg>';
const button=(action,id,ico,title,cls='small-action')=>`<button class="${cls}" data-action="${action}" data-id="${id}" title="${title}" aria-label="${title}">${action==='record'?'<svg class="drawn-microphone" aria-hidden="true"><use href="#art-mic"/></svg>':icon(action==='importAudio'?'download':action.startsWith('up')?'up':action==='downIntro'?'down':ico)}${action==='importAudio'?'<span>匯入</span>':action==='playOriginal'?'<span>聽原音</span>':''}</button>`;
const time=n=>{n=Math.max(0,Math.round(n||0));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};
const find=id=>A.inventoryClips(state).find(c=>c.id===id);
function rememberPreviousAudio(c){if(c.blob)lastAudioUndo={id:c.id,blob:c.blob,duration:c.duration,trimStart:c.trimStart,trimEnd:c.trimEnd}}
function clearToast(){clearTimeout(toast.timer);$('#toast').classList.remove('show');syncDesktopNotices()}
function toast(message){const el=$('#toast'),anchor=document.querySelector('dialog[open] .dialog-top')||(atWorktable?$('.topbar'):$('.room-return'));if(anchor)anchor.insertAdjacentElement('afterend',el);el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(clearToast,4200);syncDesktopNotices()}
async function initDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('listening-picturebook',2);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('projects'))req.result.createObjectStore('projects');if(!req.result.objectStoreNames.contains('exports'))req.result.createObjectStore('exports',{keyPath:'id'})};req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(req.error)})}
let localRevision=null,localConflict=false;
const localConflictId='local-tab-conflict-'+uid();
function dbRead(){return new Promise((resolve,reject)=>{const tx=db.transaction('projects'),store=tx.objectStore('projects'),data=store.get('current'),revision=store.get('local-revision');tx.oncomplete=()=>{localRevision=revision.result??null;localConflict=false;resolve(data.result)};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('讀取已中止'))})}
// Compare and write in one transaction: stale tabs retain their own draft, never replace current.
function writeLocalProject(snapshot,previous,isCurrent=()=>true){return new Promise((resolve,reject)=>{let tx,timer,conflict=false,nextRevision,finished=false;const finish=error=>{if(finished)return;finished=true;clearTimeout(timer);error?reject(error):resolve()};try{tx=db.transaction(['projects','exports'],'readwrite');const projects=tx.objectStore('projects'),archives=tx.objectStore('exports');tx.oncomplete=()=>{if(conflict){localConflict=true;const error=Error('另一個分頁已更新專案。本頁內容已另存資料庫草稿，請關閉其他分頁後重新載入，再從資料庫選擇要繼續的版本。');error.code='LOCAL_CONFLICT';finish(error)}else{localRevision=nextRevision;localConflict=false;finish()}};tx.onerror=()=>finish(tx.error||Error('儲存失敗'));tx.onabort=()=>finish(tx.error||Error('儲存已中止'));timer=setTimeout(()=>{try{tx.abort()}catch{}finish(Error('儲存逾時，原本保存的內容未變更'))},15000);const read=projects.get('local-revision');read.onsuccess=()=>{try{if(!isCurrent())throw Error('操作已取消或帳號已變更，原專案保留');if((read.result??null)!==localRevision){conflict=true;archives.put({id:localConflictId,kind:'draft',origin:'local-tab-conflict',title:(previous||snapshot).title+'（分頁保留版本）',createdAt:Date.now(),project:previous||snapshot});return}if(previous)archives.put({id:uid(),kind:'draft',title:previous.title,createdAt:Date.now(),project:previous});nextRevision=uid();projects.put(snapshot,'current');projects.put(nextRevision,'local-revision')}catch(error){try{tx.abort()}catch{}finish(error)}};}catch(error){try{tx?.abort()}catch{}finish(error)}})}
// UI generation only: transaction ordering, snapshots and the 450ms debounce stay unchanged.
let saveEditEpoch=0,saveStatusProblem=null;
function setSaveStatus(message,problem=false){saveStatusProblem=problem?{projectId:state.projectId,text:message}:null;const el=$('#saveState');if(el.textContent!==message)el.textContent=message}
function save(){clearTimeout(saveTimer);saveEditEpoch++;if(saveStatusProblem?.projectId!==state.projectId||saveStatusProblem?.text!==$('#saveState').textContent)setSaveStatus('正在收好這一頁…');saveTimer=setTimeout(()=>persist(),450);invalidateExport()}
function persist(snapshot=structuredClone(state),{syncConflict=true}={}){
 const epoch=saveEditEpoch,current=()=>epoch===saveEditEpoch&&snapshot.projectId===state.projectId;
 if(!db){setSaveStatus('尚未保存，請下載專案備份',true);return Promise.resolve({ok:false,error:Error('本機資料庫尚未開啟')})}
 saveChain=saveChain.catch(()=>{}).then(()=>writeLocalProject(snapshot)).then(async()=>{
  if(current())setSaveStatus(rec?'稿文與設定已保存；本次錄音尚在處理':'已自動保存於這台裝置');
  let syncQueued=true;try{await window.StudioSync?.capture(snapshot)}catch{syncQueued=false;if(current())setSaveStatus('已存本機；雲端排程未完成，請重試同步',true)}
  return {ok:true,syncQueued};
 });
 return saveChain.catch(async error=>{
  if(error.code==='LOCAL_CONFLICT'){setSaveStatus('分頁衝突：本頁已另存資料庫草稿',true);if(syncConflict)try{await window.StudioSync?.capture(snapshot)}catch{}toast(error.message)}
  else{setSaveStatus('尚未保存，請下載專案備份',true);toast('自動保存失敗，請立即下載專案備份。')}
  return {ok:false,error,conflict:error.code==='LOCAL_CONFLICT'};
 });
}
let pendingRecording=null,recordingCommitInFlight=false;
function showPendingRecording(message){let box=$('#recordRecovery');if(!box){box=document.createElement('section');box.id='recordRecovery';box.className='record-recovery';box.innerHTML='<p role="status" aria-live="polite"></p><button type="button" class="secondary" data-recovery="save">重試保存這段</button><button type="button" class="secondary" data-recovery="download">下載這次原始錄音</button><button type="button" class="secondary" data-recovery="discard">放棄這次錄音</button>';document.body.append(box);box.addEventListener('click',async e=>{const kind=e.target.closest('[data-recovery]')?.dataset.recovery,p=pendingRecording;if(!p||!kind||p.busy)return;if(kind==='download'){download(p.blob,'待恢復錄音.'+(p.blob.type.includes('mp4')?'m4a':p.blob.type.includes('wav')?'wav':'webm'));return}if(kind==='discard'){if(confirm('放棄尚未保存的這次錄音？原本錄音保持不變。')){pendingRecording=null;box.hidden=true}return}if(!p.candidate)return;p.busy=true;arrangementBusy=true;renderBusy();box.querySelectorAll('button').forEach(b=>b.disabled=true);box.querySelector('p').textContent='正在保存恢復片段…';const result=await commitRecordingCandidate(p);p.busy=false;arrangementBusy=false;renderBusy();if(result.ok){pendingRecording=null;box.hidden=true;$('#clip-'+p.clipId)?.querySelector('[data-action=toggleClipPlayback]')?.focus({preventScroll:true});toast('恢復片段已保存於這台裝置，請先試聽。')}else showPendingRecording('仍未保存：'+result.error.message+'。請先下載這次原音，保留本頁。')})}box.hidden=false;box.querySelector('p').textContent=message+' 原本錄音不變；待恢復片段只在本頁記憶體，關頁或系統終止可能遺失。';box.querySelectorAll('button').forEach(b=>b.disabled=false);box.querySelector('[data-recovery=save]').disabled=!pendingRecording?.candidate;if(document.visibilityState==='visible')box.querySelector('button:not(:disabled)')?.focus({preventScroll:true});}
async function commitRecordingCandidate(p){const c=find(p.clipId);if(!c||state.projectId!==p.projectId)return {ok:false,error:Error('專案或片段已切換，請下載這次原音')};clearTimeout(saveTimer);const snapshot=structuredClone(state),target=A.inventoryClips(snapshot).find(c=>c.id===p.clipId);Object.assign(target,p.candidate);recordingCommitInFlight=true;let result;try{result=await persist(snapshot,{syncConflict:false})}finally{recordingCommitInFlight=false}if(result.ok){$('#saveState').textContent=result.syncQueued===false?'這次錄音已存本機；雲端排程未完成，請重試同步':'這次錄音已保存於這台裝置';rememberPreviousAudio(c);Object.assign(c,p.candidate);invalidateExport();A.clearCache();meta();renderNav();renderChapter()}return result}

function invalidateExport(){compiledBlob=null;exportMade=false;if(fullURL){URL.revokeObjectURL(fullURL);fullURL=null;$('#fullAudio').pause();$('#fullAudio').removeAttribute('src');$('#exportResult').hidden=true;$('#exportStatus').textContent='內容已更新，請重新串接音檔。'}}
function endChapterClips(){return[...(state.settings.rounds>1&&state.replay?[state.replay]:[]),state.end]}
function currentClips(){if(active==='optionLabels')return (state.optionLabels||[]).filter(c=>!c.codeArchived);if(active==='intro')return [...state.intro,state.start];if(active==='end')return endChapterClips();const s=state.sections.find(s=>s.id===active);return s?A.sectionClips(s):[]}
function chapterFor(id){if(state.optionLabels?.some(c=>c.id===id))return'optionLabels';if([...state.intro,state.start].some(c=>c.id===id))return'intro';if(state.end.id===id||state.replay?.id===id)return'end';return state.sections.find(s=>A.sectionClips(s).some(c=>c.id===id))?.id||'intro'}
function meta(){const clips=A.allClips(state),done=clips.filter(c=>c.blob).length,pct=Math.round(done/clips.length*100),d=A.duration(state);$('#progressLabel').textContent=`${state.sections.length} 個大題 · ${done} / ${clips.length} 段已錄好`;$('#durationLabel').textContent=done?'完整音檔約 '+time(d)+(d>2400?'（超過 40 分鐘上限）':''):'還沒有錄音';$('#progressPercent').innerHTML=pct+'<small>%</small>';$('#progressRing').style.strokeDashoffset=126*(1-pct/100);renderWorktable()}

let atWorktable=true,exportMade=false;
function renderWorktable(){
 if(!$('#worktable'))return;
 const clips=A.allClips(state),done=clips.filter(c=>c.blob).length,recorded=done===clips.length,arranged=!!state.workflow?.arranged,ready=recorded&&arranged;
 $('#homeProjectTitle').value=state.title;
 $('#homeProgress').textContent=state.sections.length+' 個大題 · '+done+' / '+clips.length+' 段聲音已收好';
 $('.entrance-record').classList.toggle('complete',recorded);
 $('.entrance-arrange').classList.toggle('complete',arranged);
 $('.entrance-export').classList.toggle('ready',ready&&!exportMade);
 $('.entrance-export').classList.toggle('complete',exportMade);
 for(const [role,label,complete] of [['record','點麥麥，進入錄音出題',recorded],['arrange','點拍仔，設定留白與重播',arranged],['export','點小封，試聽與輸出音檔',exportMade]])$('.entrance-'+role).setAttribute('aria-label',label+'；'+(complete?'已完成':'尚未完成'));
 $('#recordEntryStatus').textContent=recorded?'全部錄好了':done+' / '+clips.length+' 段已錄好';
 $('#arrangeEntryStatus').innerHTML=arranged?'節奏已確認':'<span class="arrange-status-full">點時鐘，排好播放節奏</span><span class="arrange-status-compact">留白與重播</span>';
 $('#exportEntryStatus').textContent=exportMade?'音檔已打包':ready?'全部就緒！點我輸出':'進入試聽與輸出';
 $('#finishTicket').classList.toggle('ready',ready);$('#worktable').classList.toggle('all-ready',ready);
 $('#finishTitle').textContent=exportMade?'你的聽力測驗，已經打包好了！':ready?'三、二、一，聽力測驗準備發聲！':'每完成一站，夥伴就會亮起來。';

 $('#workroom').classList.toggle('export-ready',ready);$('#rhythmConfirmedText').textContent=arranged?'✓ 這份試卷的播放節奏已確認。調整後請再確認一次。':'按下確認，收好這份試卷的留白與重播設定。';
}
function goWorktable(){if(rec||building)return;clearToast();stopPreview();atWorktable=true;$('#worktable').hidden=false;$('#workroom').hidden=true;renderWorktable();syncPhoneRoom();if(page==='library')$('.cabinet-entry').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}
function enterRoom(p){if(rec||building)return;clearToast();if(page!==p)stopPreview();atWorktable=false;$('#worktable').hidden=true;$('#workroom').hidden=false;switchPage(p);if(p==='record')renderChapter();$('#roomLabel').textContent=p==='record'?'01 · 麥麥的錄題桌':p==='arrange'?'02 · 拍仔的時鐘牆':p==='library'?'資料庫 · 已匯出音檔':'03 · 小封的打包室';syncPhoneRoom();window.scrollTo({top:0,behavior:'smooth'})}
function invalidateRhythm(){state.workflow={...(state.workflow||{}),arranged:false};exportMade=false}

function render(){if(state.settings.optionLabelsEnabled)ensureOptionLabels();if(!state.sections.some(s=>s.id===active)&&!['intro','end','optionLabels'].includes(active))active='intro';$('#projectTitle').value=state.title;meta();renderNav();renderChapter();renderSettings();renderExport();$('#autoNext').checked=state.settings.autoNext;$('#silenceThreshold').value=state.settings.silenceThreshold;for(const k of ['noiseCapture','cleanup','normalize'])$('#'+k).checked=state.settings[k];$('#sampleRate').value=state.settings.sampleRate;$('#echoCapture').checked=A.captureOptions(state.settings).echoCancellation;$('#gentleProcessing').checked=state.settings.gentleProcessing===true;$('#captureBitrate').value=String(state.settings.captureBitrate||0);renderBusy()}
function renderNav(){const chapters=[{id:'optionLabels',title:'連唸與代號',icon:'headphones',clips:state.optionLabels||[]},{id:'intro',title:'測驗開場',icon:'book',clips:[...state.intro,state.start]},...state.sections.map(s=>({id:s.id,title:s.title,short:(String(s.title).match(/^\s*([A-Z][.、．]|(?:II|III|IV|VI|VII|VIII|IX)[.、．]|[（(][一二三四五六七八九十]+[）)]|[一二三四五六七八九十]+[、．]|Part\s+[A-Z])\s+\S/)||[])[1],icon:'mic',clips:A.sectionClips(s)})),{id:'end',title:'結束提醒',icon:'leaf',clips:endChapterClips().filter(c=>!c.omitFromPlayback||c.script||c.blob)}];$('#chapterNav').innerHTML=chapters.map(c=>`<button class="chapter-button ${c.id===active?'active':''} ${c.clips.every(x=>x.blob)?'chapter-complete':''}" data-action="chapter" data-id="${c.id}" title="${esc(c.title)}" ${c.id===active?'aria-current="page"':''}>${icon(c.icon)}<span>${esc(c.short?c.short.replace(/[.、．]$/,'')+' 大題':c.title)}</span><span class="nav-count">${c.clips.filter(x=>x.blob).length}/${c.clips.length}</span></button>`).join('');{const nav=$('#chapterNav'),strip=[nav,nav.parentElement].find(e=>e&&e.scrollWidth>e.clientWidth+1),selected=nav.querySelector('[aria-current=page]');if(strip&&selected){const a=strip.getBoundingClientRect(),b=selected.getBoundingClientRect(),pad=strip===nav?56:6;let left=strip.scrollLeft;if(b.left<a.left+6)left-=a.left+6-b.left;else if(b.right>a.right-pad)left+=b.right-a.right+pad;strip.scrollTo({left,top:0})}}}
function card(c,index){const recording=rec?.clipId===c.id;return `<article class="clip-card ${active!=='intro'?'compact-stimulus':''} ${active==='intro'?'postcard':active==='end'?'envelope-card':'cassette-card'} ${c.blob?'has-audio':''} ${recording?'recording':''}" id="clip-${c.id}"><div class="clip-main"><span aria-hidden="true" class="clip-badge ${index%3===1?'blue':index%3===2?'green':''}">${icon(c.blob?'check':index%3===1?'book':'mic')}</span><div class="clip-info"><div class="clip-title">${c.speaker?`<span class="speaker-dot speaker-${c.speaker}">${esc(c.speakerName||roleName(c.speaker))}</span>`:''}${esc(c.label)} <span class="status-tag">${recording?'錄音中':c.blob?'已錄好':'等待你的聲音'}</span></div><textarea class="clip-script" data-script="${c.id}" aria-label="${esc(c.label)}朗讀稿" placeholder="寫下這一段的朗讀稿…" rows="1">${esc(c.script)}</textarea></div><div class="clip-actions"><button class="clip-illustrated-action" data-action="record" data-id="${c.id}" aria-label="${recording?'正在錄音':c.blob?'重新錄製這一段':'錄下這一段'}"><svg aria-hidden="true" class="illustrated-mic"><use href="#art-mic"/></svg><span>${recording?'錄音中…':c.blob?'重錄':'錄音'}</span></button></div></div><div class="clip-audio-status"><span class="clip-audio-state">${recording?'● 正在錄音':c.blob?'✓ 已錄好':'尚未錄音'}</span><span class="clip-time">${c.blob?A.effective(c).toFixed(1)+' 秒':'—'}</span><button class="clip-playback" data-action="toggleClipPlayback" data-id="${c.id}" ${!c.blob||recording?'disabled':''} aria-label="試聽這一段">▶ 試聽</button></div><div class="clip-bottom">${button('importAudio',c.id,'upload','匯入音檔','')}${c.blob?`<button data-action="editClip" data-id="${c.id}">${icon('sliders')}剪輯</button>`:''}${lastAudioUndo?.id===c.id?`<button data-action="undoAudio" data-id="${c.id}" title="復原最近一次替換或刪除前的音檔；僅限本次開啟期間">↶ 復原</button>`:''}</div>${editClip===c.id&&c.blob?`<div class="clip-editor"><button class="close-clip-editor" data-action="closeClipEditor">完成剪輯 ✓</button><div class="waveform-paper"><div id="wave-editor-${c.id}" class="wave-editor" role="group" aria-label="波形剪輯"></div><p class="wave-help">拖曳左右邊界，選出要保留的聲音。數字欄位也能精確調整。</p><button class="secondary" data-action="playSelection" data-id="${c.id}">${icon('play')}試聽選取範圍</button></div><div>保留原音中的範圍（秒） · 原音 ${c.duration.toFixed(2)} 秒</div><label>起點 <input type="number" min="0" max="${c.duration}" step="0.05" value="${(c.trimStart||0).toFixed(2)}" data-trim="start" data-id="${c.id}"></label><label>終點 <input type="number" min="0.02" max="${c.duration}" step="0.05" value="${(c.trimEnd??c.duration).toFixed(2)}" data-trim="end" data-id="${c.id}"></label><button data-action="resetTrim" data-id="${c.id}" class="quiet">還原範圍</button><div class="chapter-controls">${button('playOriginal',c.id,'play','播放原音','secondary')}<button class="quiet delete-text" data-action="deleteAudio" data-id="${c.id}">${icon('trash')}刪除此段錄音</button></div></div>`:''}</article>`}
function renderChapter(){restoreDeckCard();if(active==='optionLabels'){renderOptionLabels();return}let clips=currentClips();const s=state.sections.find(s=>s.id===active),idx=state.sections.indexOf(s);const theme=active==='intro'?'coral':active==='end'?'pink':['violet','aqua','sunny'][idx%3];$('#recordPage').dataset.theme=theme;$('#chapterArt').innerHTML='<svg><use href="#art-'+(active==='intro'?'mic':active==='end'?'envelope':'paper')+'"/></svg>'; $('#chapterNumber').textContent=active==='intro'?'PROLOGUE':active==='end'?'EPILOGUE':'CHAPTER '+String(idx+1).padStart(2,'0');$('#chapterTitle').textContent=active==='intro'?'測驗開場錄音':active==='end'?'最後一句，為測驗畫下句點。':s.title;$('#chapterDesc').textContent=active==='intro'?'英文、中文交替說明；可自行加段、排序與錄音。':active==='end'?'清楚提醒測驗結束，接著完成書寫測驗。':'說完一段、稍作停頓，下一段錄音會自動接上。';$('#pageNumber').textContent=String(active==='intro'?1:active==='end'?state.sections.length+2:idx+2).padStart(2,'0');if(s){$('#clips').innerHTML=`<div class="chapter-head"><input class="chapter-rename" data-section-title="${s.id}" aria-label="大題名稱" value="${esc(s.title)}" maxlength="60">`+arrangementControls(s,true)+groupReplayControls(s)+'</div>'+(s.heading?card(s.heading,0):'')+card(s.prompt,0).replace('class="clip-card ','class="clip-card section-guide ')+s.questions.map((q,i)=>`${renderSharedPassages(s,q)}<div class="question-label"><span><b class="question-number">${q.isExample?'例':String(s.questions.slice(0,i+1).filter(x=>!x.isExample).length).padStart(2,'0')}</b>${q.isExample?'例題':'第 '+s.questions.slice(0,i+1).filter(x=>!x.isExample).length+' 題'}</span>${arrangementControls(q,false)}<div class="question-tools">${button('upQuestion',q.id,'up','往前移一題')}${button('deleteQuestion',q.id,'trash','刪除這一題')}</div></div>${q.numberClip&&q.arrangement?.numberEnabled!==false?card(q.numberClip,0):''}${q.contentClips?A.questionClips(q).filter(c=>!q.options.includes(c)).map(card).join(''):(q.arrangement?.mode==='dialogue'?'':card(q.stem,0))+renderDialogue(q)}${q.arrangement?.recordOptions===false?'':q.options.map((c,j)=>card(c,j+1)).join('')}`).join('');$('#chapterActions').innerHTML=`<div class="chapter-controls"><button class="secondary" data-action="addQuestion" data-id="${s.id}">${icon('plus')}加一個小題</button><button class="secondary" data-action="upSection" data-id="${s.id}">${icon('up')}大題往前移</button><button class="quiet delete-text" data-action="deleteSection" data-id="${s.id}">${icon('trash')}移除大題</button></div>`}else if(active==='intro'){$('#clips').innerHTML=renderIntroRoute()+'<div class="intro-pair-grid">'+state.intro.map((c,i)=>introSegment(c,i)).join('')+'</div>'+'<div class="start-cue-label">接著，播放測驗開始提醒</div>'+card(state.start,state.intro.length);$('#chapterActions').innerHTML='<div class="intro-add-paper"><button class="secondary" data-action="addIntro">'+icon('plus')+'再加一段開場</button><p>新增時會接續上一段的語言，預設中英文交替。</p></div>'}else{$('#clips').innerHTML=clips.map((c,i)=>(c===state.replay?'<div class="start-cue-label replay-cue">整份重播前播放（第 1 輪結束、第 2 輪開始之前）・稿子留空就不播'+(c.script||c.blob?'':'<button type="button" class="replay-fill">填入建議句</button>')+'</div>':clips.length>1?'<div class="start-cue-label">最後播放：測驗結束提醒</div>':'')+card(c,i)).join('');$('#chapterActions').innerHTML=''}renderMobileDeck();mountWaveEditor();fitScripts();syncClipPlayback()}
function renderSettings(){
 const fields=[['introGap','開場段落之間','每一段中英文說明之間。','秒','clock'],['dialogueGap','對話換人','不同說話者輪流說話之間。','秒','mic'],['sectionGap','大題之間','大題重播、換大題與開始／結束前。','秒','clock'],['questionGap','小題之間','上一題結束後，給學生想一想。','秒','leaf'],['optionGap','選項之間','題目內容到答案選項，以及選項之間。','秒','mic'],['repeats','每大題播放','每個大題連續播放幾次；1 次就是不重複。','次','book'],['rounds','整份大題播放','從第一大題開始，完整播放幾輪。','輪','headphones'],['roundGap','整份重播前','一輪結束，到下一輪開始之間。','秒','clock']];
 $('#timingSettings').innerHTML=fields.map(([key,title,desc,unit,ico],i)=>`<div class="setting-card"><div class="note-pin" aria-hidden="true"></div><span class="setting-index">${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${desc}</p><div class="painted-stepper"><svg class="timer-paint" viewBox="0 0 180 150" aria-hidden="true"><g filter="url(#water)"><path d="M12 64Q5 18 74 14T168 71Q178 133 87 135T12 64Z" fill="var(--dial-wash)" opacity=".7"/><path d="m42 26-8-10m103 10 10-12" stroke="var(--dial-edge)" stroke-width="5" stroke-linecap="round"/><circle cx="90" cy="73" r="52" fill="var(--dial-fill)" stroke="var(--dial-edge)" stroke-width="2.5"/><circle cx="90" cy="73" r="43" fill="#fffcf1"/><path d="M90 34v5m0 68v5m-39-39h5m68 0h5M62 45l4 4m48 48 4 4m0-56-4 4m-48 48-4 4" stroke="var(--dial-edge)" stroke-width="2" stroke-linecap="round"/><path d="m51 117-7 11m85-11 7 10" stroke="var(--dial-edge)" stroke-width="3" stroke-linecap="round"/></g></svg><button class="dial-minus" data-action="lessTiming" data-id="${key}" aria-label="減少${title}">−</button><label class="dial-value"><input type="number" data-setting="${key}" aria-label="${title}" value="${state.settings[key]}" min="${unit==='秒'?0:1}" max="${unit==='秒'?60:4}" step="${unit==='秒'?.5:1}"><span>${unit}</span></label><button class="dial-plus" data-action="moreTiming" data-id="${key}" aria-label="增加${title}">＋</button></div><span class="note-caption">${unit==='秒'?'留一點時間，想一想。':unit==='次'?'完整大題，再聽一遍。':'從第一大題，再出發。'}</span></div>`).join('');
 renderItemSettingsEntry();syncSequenceEntry();$('#sequence').innerHTML=groupReplayBoard()+`<div class="sequence-item">${state.intro.map(c=>esc(c.label)).join(' → ')}<span>依序各 1 次</span></div><div class="sequence-item">聽力測驗開始<span>1 次</span></div>`+Array.from({length:state.settings.rounds},(_,i)=>`<div class="sequence-round">第 ${i+1} 輪${i>0?' · 從第一大題重新開始':''}</div>${i>0&&state.replay&&(state.replay.script||state.replay.blob)?'<div class="sequence-replay">▶ 先播「重播提醒」：'+esc((state.replay.script||'').slice(0,40))+'</div>':''}${state.sections.map(s=>`<div class="sequence-item">${esc(s.title)}<span>${A.hasGroupReplay(s)?'題組：整組唸完再重播 1 次':'完整播放 '+state.settings.repeats+' 次'}</span></div>`).join('')}`).join('')+'<div class="sequence-item">測驗結束，請繼續完成書寫測驗<span>1 次</span></div>';
}
function renderExportOverview(){
 const order=A.order(state),used=new Set(order.filter(x=>x.kind==='clip').map(x=>x.id));
 const count=cs=>{const included=cs.filter(c=>used.has(c.id));return included.filter(c=>c.blob).length+' / '+included.length+' 段已錄'};
 return '<ol class="export-flow" aria-label="播放階段總覽"><li><span class="flow-icon" aria-hidden="true">'+icon('mic')+'</span><strong>1 · 開場與開始提醒</strong><span>'+count([...state.intro,state.start])+'</span><small>依段落順序播放一次</small></li><li><span class="flow-icon" aria-hidden="true">'+icon('book')+'</span><strong>2 · 大題測驗</strong><small>每大題 '+state.settings.repeats+' 次 · 全部大題共 '+state.settings.rounds+' 輪</small><div class="flow-sections">'+state.sections.map(sec=>'<span><b>'+esc(sec.title)+'</b>'+count(A.sectionClips(sec))+'</span>').join('')+'</div></li><li><span class="flow-icon" aria-hidden="true">'+icon('headphones')+'</span><strong>3 · 結束提醒</strong><span>'+count(endChapterClips().filter(c=>!c.omitFromPlayback||c.script||c.blob))+'</span><small>'+(state.settings.rounds>1&&(state.replay?.script||state.replay?.blob)?'重播提醒在第 2 輪前；結束提醒最後播放':'最後播放一次')+'</small></li></ol>';
}
function renderExport(){const clips=A.allClips(state),missing=clips.filter(c=>!c.blob);$('#exportTitle').textContent=state.title;$('#exportSummary').textContent=`${state.sections.length} 個大題 · 每大題 ${state.settings.repeats} 次 · 共 ${state.settings.rounds} 輪 · 約 ${time(A.duration(state))}`;$('#exportWarnings').innerHTML=(A.duration(state)>2400?'<p class="export-readiness">⚠ 整份音檔約 '+Math.ceil(A.duration(state)/60)+' 分鐘，超過 40 分鐘上限。請縮短留白或減少重播，或分成兩份製作。</p>':'')+'<p class="export-readiness">'+(missing.length?'還有 '+missing.length+' 段待錄；以下顯示每個階段的完成度。':'所有聲音都準備好了，來聽聽看吧。')+'</p>'+renderExportOverview();const inactive=A.inventoryClips(state).filter(c=>c.blob&&!clips.some(a=>a.id===c.id));if(inactive.length)$('#exportWarnings').innerHTML+='<p>保留 '+inactive.length+' 段停用錄音，不列入本次輸出。可在本題錄音安排切回原設定；專案備份會一併保存。</p>';$('#exportWarnings').innerHTML+='<p>'+itemPlaybackSummary()+'</p><div class="rhythm-missing"><button data-action="enterArrange">'+(state.workflow?.arranged?'到拍仔查看詳細播放順序':'先找拍仔，確認播放節奏')+'</button></div>'}
function renderBusy(){StudioAmbience.label();const stop=$('[data-action=stopRecord]'),next=$('[data-action=nextRecord]');if(stop)stop.textContent=rec?.phase==='recording'?'停止並保存':rec?.phase==='saving'?'正在保存…':'取消錄音';if(next)next.textContent='保存，下一段';const locked=!!rec||building||arrangementBusy;document.querySelectorAll('[data-action]').forEach(el=>{const ok=['stopRecord','nextRecord'].includes(el.dataset.action);const clips=currentClips(),index=clips.findIndex(c=>c.id===mobileClipId),boundary=(el.dataset.action==='mobilePrevious'&&index<=0)||(el.dataset.action==='mobileNext'&&index>=clips.length-1);el.disabled=boundary||(locked&&!ok)||(el.dataset.action==='toggleClipPlayback'&&!find(el.dataset.id)?.blob)});document.querySelectorAll('[data-arrangement],[data-trim],[data-option-count],[data-setting],[data-section-title],#projectTitle,#homeProjectTitle,[data-intro-lang],[data-role-name],[data-role-tone],#cleanup,#normalize,#noiseCapture,#echoCapture,#gentleProcessing,#captureBitrate,#sampleRate,#autoNext,#silenceThreshold').forEach(el=>el.disabled=locked);document.querySelectorAll('[data-tab]').forEach(el=>el.disabled=locked);$('#buildButton').disabled=locked;if(next)next.disabled=!rec||rec.phase!=='recording';if(stop)stop.disabled=rec?.phase==='saving';document.querySelectorAll('[data-script]').forEach(el=>el.disabled=arrangementBusy||rec?.phase==='saving');window.MobileReading?.sync()}
function switchPage(p){if(rec||building)return;if(page!==p)stopPreview();page=p;document.querySelectorAll('.character-entrance').forEach(el=>{const selected=el.dataset.action.toLowerCase()==='enter'+p;el.classList.toggle('selected-workspace',selected);if(selected)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current')});for(const name of ['record','arrange','export','library'])$('#'+name+'Page').hidden=name!==p;document.querySelectorAll('[data-tab]').forEach(el=>{el.classList.toggle('active',el.dataset.tab===p);el.setAttribute('aria-selected',String(el.dataset.tab===p))});if(p==='export')renderExport()}
let previewFeedbackDone=null;
function stopPreview(){previewFeedbackDone?.();previewFeedbackDone=null;previewEpoch++;stopArchivePlayer();window.speechSynthesis?.cancel();if(waveEditor)waveEditor.pause();if(previewAudio){previewAudio.pause();previewAudio=null}if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}$('#fullAudio').pause();previewClipId=null;syncClipPlayback()}
function syncClipPlayback(){document.querySelectorAll('.clip-playback').forEach(b=>{const playing=previewClipId===b.dataset.id&&previewAudio&&!previewAudio.paused;b.innerHTML=icon(playing?'stop':'headphones')+'<span>'+(playing?'停止試聽':'試聽')+'</span>';b.setAttribute('aria-pressed',String(!!playing));b.setAttribute('aria-label',playing?'停止試聽這一段':'試聽這一段')});window.MobileReading?.playback()}
async function play(c,original=false){StudioAmbience.quiet();if(!c?.blob||rec||building)return;stopPreview();const operation=previewEpoch,project=state,source=c.blob,version=c.version;const current=()=>operation===previewEpoch&&state===project&&!rec&&!building&&find(c.id)===c&&c.blob===source&&c.version===version;const finishFeedback=desktopTask(original?'正在準備原音…':'正在準備剪輯後的聲音…');previewFeedbackDone=finishFeedback;toast(original?'正在準備原音…':'正在準備剪輯後的聲音…');try{const blob=original?c.blob:await A.preview(resolveVoice(c),state.settings);if(!current())return;previewURL=URL.createObjectURL(blob);previewAudio=new Audio(previewURL);previewClipId=c.id;const audio=previewAudio;audio.onended=()=>{if(previewAudio===audio)stopPreview()};await audio.play();if(!current()){audio.pause();return}syncClipPlayback();toast(original?'播放原音':'播放剪輯後的聲音')}catch(e){if(current())toast('無法播放這段音檔：'+e.message)}finally{finishFeedback();if(previewFeedbackDone===finishFeedback)previewFeedbackDone=null}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function safeName(){return (state.title||'聽力測驗').replace(/[\\/:*?"<>|]/g,'_')}
let audioImportEpoch=0,restoreEpoch=0,projectSwitching=false;
async function replaceLocalProject(incoming,prepare=async()=>{},isCurrent=()=>true){if(rec||building||arrangementBusy||projectSwitching)throw Error("請先完成目前錄音或處理，再開啟專案");projectSwitching=true;arrangementBusy=true;clearTimeout(saveTimer);renderBusy();try{await waitImportStorage(saveChain.catch(()=>{}));await prepare();const previous=structuredClone(state);await commitImportedSwitch(previous,incoming,isCurrent);state=incoming;stopPreview();stopArchivePlayer();lastAudioUndo=null;invalidateAudioImport();A.clearCache();$("#saveState").textContent="已自動保存於這台裝置";}finally{projectSwitching=false;arrangementBusy=false;renderBusy()}}
function invalidateAudioImport(){audioImportEpoch++}
/* Desktop operation feedback is separate from persistence success. Never delays user activation. */
let desktopTaskSequence=0;
function desktopTask(message){const id=++desktopTaskSequence;let el=document.querySelector('#desktopTaskStatus');if(!el){el=document.createElement('p');el.id='desktopTaskStatus';el.className='desktop-task-status';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el)}el.textContent=message;el.setAttribute('aria-busy','true');syncDesktopNotices();return()=>{if(id===desktopTaskSequence){el.textContent='';el.removeAttribute('aria-busy');syncDesktopNotices()}}}
async function importAudio(file){const epoch=++audioImportEpoch,project=state,c=find(importTarget);if(!file||!c)return;const baseProjectId=state.projectId,baseVersion=c.version,baseBlob=c.blob,baseFields=JSON.stringify(c);if(file.size>100*1024*1024)return toast('單段音檔請小於 100 MB。');const finishFeedback=desktopTask('正在讀取與解碼音檔…原音尚未替換。');try{const b=await A.decode(file);if(epoch!==audioImportEpoch||state!==project||state.projectId!==baseProjectId||find(c.id)!==c||c.version!==baseVersion||c.blob!==baseBlob||JSON.stringify(c)!==baseFields||rec||building){toast('匯入已取消：專案或錄音狀態已變更，原音未替換。');return}if(!Number.isFinite(b.duration)||b.duration<.02)throw Error('音檔長度無效');if(b.duration>600)throw Error('單段音檔請小於 10 分鐘');if(baseBlob&&!confirm('這一段已經有錄音了。\n要用匯入的音檔取代嗎？\n（取代後仍可按「復原」找回原錄音）')){toast('已取消匯入，原錄音保留。');return}rememberPreviousAudio(c);c.blob=new Blob([file],{type:file.type.startsWith('audio/')?file.type:'audio/octet-stream'});c.duration=b.duration;c.trimStart=0;c.trimEnd=b.duration;c.version++;A.clearCache();save();render();toast('音檔已載入，正在保存；請確認保存狀態後再離開。')}catch(e){if(epoch!==audioImportEpoch||state!==project||find(c.id)!==c)return;toast('無法匯入：'+e.message)}finally{finishFeedback()}}
function toBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
async function backup(){if(rec||building)return;const finishFeedback=desktopTask('正在整理錄音與專案備份…');try{toast('正在收好錄音與設定…');await persist();const copy=structuredClone(state);for(const c of A.inventoryClips(copy))if(c.blob)c.blob=await toBase64(c.blob);download(new Blob([JSON.stringify(copy)],{type:'application/json'}),safeName()+'.listenbook');toast('專案備份已準備下載，換裝置時可重新開啟。')}catch(e){toast('備份失敗：'+e.message)}finally{finishFeedback()}}
function validateProject(s){if(!s||s.format!=='listenbook'||s.version!==1||!Array.isArray(s.sections)||!s.sections.length||s.sections.length>20||!Array.isArray(s.intro)||(s.intro.length<1||s.intro.length>40)||!s.start||!s.end||(s.replay!==undefined&&(!s.replay||typeof s.replay!=='object'))||typeof s.title!=='string'||!s.settings)throw Error('不是有效的小書專案');const keys=['sectionGap','questionGap','optionGap','roundGap'];for(const k of keys)if(!Number.isFinite(s.settings[k])||s.settings[k]<0||s.settings[k]>60)throw Error('留白設定無效');for(const k of ['repeats','rounds'])if(!Number.isInteger(s.settings[k])||s.settings[k]<1||s.settings[k]>4)throw Error('重播設定無效');const ids=new Set();for(const sec of s.sections){if(typeof sec.id!=='string'||!/^[\w-]+$/.test(sec.id)||typeof sec.title!=='string'||!Array.isArray(sec.questions)||sec.questions.length>50||!sec.questions.length)throw Error('大題結構無效');for(const q of sec.questions)if(typeof q.id!=='string'||!/^[\w-]+$/.test(q.id)||!q.stem||!Array.isArray(q.options)||q.options.length>6||(q.turns&&(!Array.isArray(q.turns)||q.turns.length>40)))throw Error('小題結構無效')}for(const k of ['introGap','dialogueGap'])if(s.settings[k]!==undefined&&(!Number.isFinite(s.settings[k])||s.settings[k]<0||s.settings[k]>60))throw Error('段落留白設定無效');validateImportedStructure(s);validateItemPlayback(s);validateArrangements(s);const clips=A.inventoryClips(s);if(clips.length>500)throw Error('專案片段過多');for(const c of clips){if(!c||typeof c.id!=='string'||!/^[\w-]+$/.test(c.id)||ids.has(c.id)||typeof c.label!=='string'||typeof c.script!=='string')throw Error('錄音資料無效');ids.add(c.id);if(c.voiceStyle&&!['natural','bright','warm'].includes(c.voiceStyle))throw Error('音色設定無效');if(c.speaker&&!['A','B'].includes(c.speaker))throw Error('角色設定無效');if(c.blob&&(!Number.isFinite(c.duration)||c.duration<=0||c.duration>600||!Number.isFinite(c.trimStart)||c.trimStart<0||!Number.isFinite(c.trimEnd)||c.trimEnd>c.duration+.02||c.trimEnd-c.trimStart<.02))throw Error('錄音範圍無效')}return s}
