function suspendCapture(){clearTimeout(saveTimer);if(rec)interruptRecording(rec,'畫面已暫停，已停止連續換段；回來後請手動開始。');if(rec?.phase==='saving'||recordingCommitInFlight||projectSwitching)return;persist()}
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspendCapture()});
window.addEventListener('pagehide',suspendCapture);
(async()=>{render();try{db=await initDB();const saved=await dbRead();if(saved){state=migrateProject(validateProject(saved));active='intro';render();$('#saveState').textContent='已開啟上次的聽力試卷'}else $('#saveState').textContent='錄音會自動保存於這台裝置';await refreshLibrary()}catch(e){$('#saveState').textContent='自動保存無法使用，請下載備份';toast('無法讀取裝置保存空間。仍可錄音，請記得下載專案備份。')}finally{window.StudioLoaded=true}})();

